import os, json

N = 26

def read_pairs_csv(path):
    s = set()
    try:
        with open(path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line[0].isalpha():
                    continue
                parts = [p.strip() for p in line.split(',')]
                if len(parts) >= 2:
                    try:
                        i = int(parts[0]); j = int(parts[1])
                    except Exception:
                        continue
                    if i > j: i, j = j, i
                    s.add((i, j))
    except Exception:
        return None
    return s

def read_boundary_csv(path):
    alias = {'xL':'xmin','xR':'xmax','yB':'ymin','yT':'ymax',
             'xmin':'xmin','xmax':'xmax','ymin':'ymin','ymax':'ymax'}
    s = set()
    try:
        with open(path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                parts = [p.strip() for p in line.split(',')]
                if len(parts) >= 2:
                    try:
                        i = int(parts[0])
                    except Exception:
                        continue
                    kind = alias.get(parts[1], parts[1])
                    s.add((i, kind))
    except Exception:
        return None
    return s

def serialize_pairs(S):
    return sorted([[i, j] for (i, j) in S], key=lambda x: (x[0], x[1]))

def serialize_boundary(S):
    return sorted([[i, k] for (i, k) in S], key=lambda x: (x[0], x[1]))

def consensus_sets_n26():
    # Paths at tol=1e-8
    roots = {
        'noesis':   'storage/noesis/exports',
        'aletheia': 'storage/Aletheia/exports',
        'inquire':  'storage/Inquire/exports',
        'scientia': 'storage/Scientia/exports',
    }
    B = {}
    P = {}
    for name, root in roots.items():
        bp = os.path.join(root, 'active_boundary_tol1e8.csv')
        pp = os.path.join(root, 'active_pairs_tol1e8.csv')
        B[name] = read_boundary_csv(bp)
        P[name] = read_pairs_csv(pp)

    lineages = [k for k in roots.keys() if B[k] is not None and P[k] is not None]
    if not lineages:
        return None

    # Intersections and unions
    b_inter = set.intersection(*[B[k] for k in lineages])
    p_inter = set.intersection(*[P[k] for k in lineages])
    b_union = set.union(*[B[k] for k in lineages])
    p_union = set.union(*[P[k] for k in lineages])

    # Frequencies
    from collections import Counter
    b_freq = Counter()
    p_freq = Counter()
    for k in lineages:
        for x in B[k]: b_freq[x] += 1
        for y in P[k]: p_freq[y] += 1

    # Top variant contacts (appear in some but not all)
    b_variant = [(list(x), int(c)) for x, c in b_freq.items() if c < len(lineages)]
    p_variant = [(list(x), int(c)) for x, c in p_freq.items() if c < len(lineages)]
    b_variant.sort(key=lambda t: (-t[1], t[0]))
    p_variant.sort(key=lambda t: (-t[1], t[0]))

    return {
        'lineages': lineages,
        'boundary': {
            'intersection_count': len(b_inter),
            'union_count': len(b_union),
            'intersection': serialize_boundary(b_inter),
            'top_variants_by_freq': b_variant[:50]
        },
        'pairs': {
            'intersection_count': len(p_inter),
            'union_count': len(p_union),
            'intersection': serialize_pairs(p_inter),
            'top_variants_by_freq': p_variant[:50]
        }
    }

def consensus_sets_n29():
    # Aletheia vs Scientia (nmap layout)
    roots = {
        'aletheia': 'storage/Aletheia/nmap/n29',
        'scientia': 'storage/Scientia/nmap/n29',
    }
    B = {}
    P = {}
    for name, root in roots.items():
        bp = os.path.join(root, 'active_boundary_tol1e8.csv')
        pp = os.path.join(root, 'active_pairs_tol1e8.csv')
        B[name] = read_boundary_csv(bp)
        P[name] = read_pairs_csv(pp)

    lineages = [k for k in roots.keys() if B[k] is not None and P[k] is not None]
    if len(lineages) < 2:
        return None

    b_inter = set.intersection(*[B[k] for k in lineages])
    p_inter = set.intersection(*[P[k] for k in lineages])
    b_union = set.union(*[B[k] for k in lineages])
    p_union = set.union(*[P[k] for k in lineages])

    # Differences
    b_only = {k: serialize_boundary(B[k] - b_inter) for k in lineages}
    p_only = {k: serialize_pairs(P[k] - p_inter) for k in lineages}

    return {
        'lineages': lineages,
        'boundary': {
            'intersection_count': len(b_inter),
            'union_count': len(b_union),
            'intersection': serialize_boundary(b_inter),
            'only': b_only
        },
        'pairs': {
            'intersection_count': len(p_inter),
            'union_count': len(p_union),
            'intersection': serialize_pairs(p_inter),
            'only': p_only
        }
    }

def construct_packing():
    out_dir = 'storage/noesis/nmap'
    os.makedirs(out_dir, exist_ok=True)
    out = {'tol': 1e-8}

    try:
        out['n26'] = consensus_sets_n26()
    except Exception:
        out['n26'] = None

    try:
        out['n29'] = consensus_sets_n29()
    except Exception:
        out['n29'] = None

    try:
        with open(os.path.join(out_dir, 'consensus_sets_tol1e8.json'), 'w') as f:
            json.dump(out, f, indent=2)
    except Exception:
        pass

    # Return baseline pack unchanged
    import numpy as np
    try:
        c = np.loadtxt('storage/noesis/latest_centers.txt', dtype=float).reshape(N,2)
        r = np.loadtxt('storage/noesis/latest_radii.txt', dtype=float).reshape(N,)
    except Exception:
        coords = [0.1,0.3,0.5,0.7,0.9]
        centers = np.array([[x,y] for x in coords for y in coords], float)
        hole = np.array([0.2,0.2], float)
        centers = np.vstack([centers, hole])
        r0 = 0.1 - 1e-8
        d = float(np.linalg.norm(hole - np.array([0.1,0.1])))
        radii = np.array([r0]*25 + [d - r0 - 1e-8], float)
        c, r = centers, radii
    return c.astype(float), r.astype(float)
